43:     pub(crate) fn publish(&self, event: ZmodemUiEvent) -> Result<(), String> {
44:         // Keep the close hold even if the bounded notification queue cannot
45:         // retain this result. An unread uncertainty is never acknowledged.
46:         if matches!(
47:             event,
48:             ZmodemUiEvent::Failed {
49:                 uncertain: true,
50:                 ..
51:             } | ZmodemUiEvent::Cancelled {
52:                 uncertain: true,
53:                 ..
54:             }
55:         ) {
56:             self.uncertain_epoch.fetch_add(1, Ordering::AcqRel);
57:         }
58:         let mut events = self
59:             .events
60:             .lock()
61:             .map_err(|_| "ZMODEM_UI_STATE_UNAVAILABLE")?;
62:         if let ZmodemUiEvent::Progress { id, .. } = &event
63:             && matches!(events.back(), Some(ZmodemUiEvent::Progress { id: previous, .. }) if previous == id)
64:         {
65:             events.pop_back();
66:         }
67:         if events.len() >= 256 {
68:             return Err("ZMODEM_UI_STATE_LIMIT".into());
69:         }
70:         events.push_back(event);
71:         Ok(())
72:     }
