275:         let (worker, driver) = tokio::join!(
276:             run(session.clone(), receiver, output, cancelled, lifecycle),
277:             async {
278:                 ready(&mut state).await?;
279:                 commands.send(TerminalCommand::Write(vec![b'a'; 8 * 1024 * 1024]))?;
280:                 let mut bytes = Vec::new();
281:                 loop {
282:                     match incoming.try_recv() {
283:                         Ok(SessionEvent::Data(data)) => bytes.extend(data),
284:                         Ok(SessionEvent::Exited { code, success }) => {
285:                             assert_eq!(code, 0);
286:                             assert!(success);
287:                             break;
288:                         }
289:                         Ok(SessionEvent::Error(error)) => return Err(error.into()),
290:                         Ok(SessionEvent::Zmodem(_)) => {
291:                             return Err("unexpected protocol notification".into());
292:                         }
293:                         Err(mpsc::TryRecvError::Disconnected) => {
294:                             return Err("bridge lost tail".into());
295:                         }
296:                         Err(mpsc::TryRecvError::Empty) => {
297:                             tokio::time::sleep(Duration::from_millis(2)).await
298:                         }
299:                     }
300:                 }
301:                 assert_eq!(bytes, b"tail after blocked input");
302:                 Ok::<_, Box<dyn Error>>(())
303:             }
304:         );
305:         driver?;
306:         worker?;
307:         assert!(matches!(
308:             *state.borrow(),
309:             TransportState::Ended(ShellEnd::Exited { code: 0 })
310:         ));
311:         assert!(fixture.received.load(Ordering::Acquire) <= 1024);
312:         session.close().await?;
313:         Ok::<_, Box<dyn Error>>(())
314:     })
315:     .await?

1146:     fn close_session_tab(&mut self, id: EntityId, window: &mut Window, cx: &mut Context<Self>) {
1147:         if self.active_modal().is_some() || self.connecting {
1148:             return;
1149:         }
1150:         // A painted close control retains its original entity. Do not select
1151:         // that target first: closing an inactive tab must retain the user's
1152:         // active pane, its command review and every other leaf's selection.
1153:         let Some(index) = self.tabs.iter().position(|tab| tab.entity_id() == id) else {
1154:             return;
